typedef long long ll;

typedef struct {
    int id;
    int x, y;
} Town;

typedef struct {
    int u, v;
    int w;
} Edge;

typedef struct {
    int parent;
    int rank;
} DSUNode;

int cmp_x(const void *a, const void *b) {
    const Town *p = (const Town *)a;
    const Town *q = (const Town *)b;
    if (p->x != q->x) return (p->x < q->x) ? -1 : 1;
    return (p->y < q->y) ? -1 : (p->y > q->y);
}

int cmp_y(const void *a, const void *b) {
    const Town *p = (const Town *)a;
    const Town *q = (const Town *)b;
    if (p->y != q->y) return (p->y < q->y) ? -1 : 1;
    return (p->x < q->x) ? -1 : (p->x > q->x);
}

int cmp_edge(const void *a, const void *b) {
    const Edge *p = (const Edge *)a;
    const Edge *q = (const Edge *)b;
    if (p->w != q->w) return (p->w < q->w) ? -1 : 1;
    return 0;
}

int find_set(DSUNode *dsu, int x) {
    if (dsu[x].parent != x)
        dsu[x].parent = find_set(dsu, dsu[x].parent);
    return dsu[x].parent;
}

int union_set(DSUNode *dsu, int a, int b) {
    a = find_set(dsu, a);
    b = find_set(dsu, b);
    if (a == b) return 0;

    if (dsu[a].rank < dsu[b].rank) {
        dsu[a].parent = b;
    } else if (dsu[a].rank > dsu[b].rank) {
        dsu[b].parent = a;
    } else {
        dsu[b].parent = a;
        dsu[a].rank++;
    }
    return 1;
}

