    for (int i = 0; i < N - 1; i++) {
        edges[m].u = tx[i].id;
        edges[m].v = tx[i + 1].id;
        edges[m].w = abs(tx[i + 1].x - tx[i].x);
        m++;

        edges[m].u = ty[i].id;
        edges[m].v = ty[i + 1].id;
        edges[m].w = abs(ty[i + 1].y - ty[i].y);
        m++;
    }

    qsort(edges, m, sizeof(Edge), cmp_edge);

    DSUNode *dsu = (DSUNode *)malloc(sizeof(DSUNode) * N);
    for (int i = 0; i < N; i++) {
        dsu[i].parent = i;
        dsu[i].rank = 0;
    }

    ll ans = 0;
    int used = 0;
    for (int i = 0; i < m && used < N - 1; i++) {
