            this.idx = idx;
            this.x = x;
            this.y = y;
        }
    }

    static class Edge implements Comparable<Edge> {
        int u, v;
        int cost;

        Edge(int u, int v, int cost) {
            this.u = u;
            this.v = v;
            this.cost = cost;
        }

        @Override
        public int compareTo(Edge other) {
            return Integer.compare(this.cost, other.cost);
        }
    }

    static class DSU {
        int[] parent;
        int[] rank;

        DSU(int n) {
            parent = new int[n];
            rank = new int[n];
            for (int i = 0; i < n; i++) parent[i] = i;
        }

        int find(int x) {
            if (parent[x] != x) parent[x] = find(parent[x]);
            return parent[x];
        }

        boolean union(int a, int b) {
            int ra = find(a);
            int rb = find(b);
            if (ra == rb) return false;

            if (rank[ra] < rank[rb]) {
                parent[ra] = rb;
            } else if (rank[ra] > rank[rb]) {
                parent[rb] = ra;
            } else {
                parent[rb] = ra;
                rank[ra]++;
            }
            return true;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int n = fs.nextInt();

        Town[] towns = new Town[n];
        for (int i = 0; i < n; i++) {
            int x = fs.nextInt();
            int y = fs.nextInt();
            towns[i] = new Town(i, x, y);
        }

        List<Edge> edges = new ArrayList<>();

        Town[] byX = towns.clone();
        Arrays.sort(byX, Comparator.comparingInt(a -> a.x));
        for (int i = 0; i < n - 1; i++) {
            Town a = byX[i];
            Town b = byX[i + 1];
            edges.add(new Edge(a.idx, b.idx, Math.abs(a.x - b.x)));
        }

        Town[] byY = towns.clone();
        Arrays.sort(byY, Comparator.comparingInt(a -> a.y));
        for (int i = 0; i < n - 1; i++) {
            Town a = byY[i];
            Town b = byY[i + 1];
            edges.add(new Edge(a.idx, b.idx, Math.abs(a.y - b.y)));
        }

        Collections.sort(edges);

        DSU dsu = new DSU(n);
        long answer = 0;
        int used = 0;

        for (Edge e : edges) {
            if (dsu.union(e.u, e.v)) {
                answer += e.cost;
                used++;
                if (used == n - 1) break;
            }
        }

        System.out.println(answer);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

