        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x):
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, x, y):
        rx, ry = self.find(x), self.find(y)
        if rx == ry:
            return False
        if self.rank[rx] < self.rank[ry]:
            self.parent[rx] = ry
        elif self.rank[rx] > self.rank[ry]:
            self.parent[ry] = rx
        else:
            self.parent[ry] = rx
            self.rank[rx] += 1
        return True


def solve():
    input_data = sys.stdin.read().strip().split()
    n = int(input_data[0])
    towns = []
    idx = 1
    for i in range(n):
        x = int(input_data[idx])
        y = int(input_data[idx + 1])
        towns.append((x, y, i))
        idx += 2

    edges = []

    # Sort by x
    towns_by_x = sorted(towns, key=lambda t: t[0])
    for i in range(n - 1):
        cost = abs(towns_by_x[i][0] - towns_by_x[i + 1][0])
        edges.append((cost, towns_by_x[i][2], towns_by_x[i + 1][2]))

    # Sort by y
    towns_by_y = sorted(towns, key=lambda t: t[1])
    for i in range(n - 1):
        cost = abs(towns_by_y[i][1] - towns_by_y[i + 1][1])
        edges.append((cost, towns_by_y[i][2], towns_by_y[i + 1][2]))

    # Kruskal's algorithm
    edges.sort()
    uf = UnionFind(n)
    total_cost = 0
    for cost, u, v in edges:
        if uf.union(u, v):
            total_cost += cost

    print(total_cost)


if __name__ == "__main__":
    solve()
